head.b:skin:
/* ---------------------------------------------------------------------------------------
[STEPS 1-10] TITAN CORE DESIGN SYSTEM
--------------------------------------------------------------------------------------- */
:root {
    --primary: #ce1212; --primary-dark: #a00d0d;
    --secondary: #37373f; --accent: #ffc107;
    --bg-body: #f8f9fa; --bg-card: #ffffff;
    --text-main: #1d1d1f; --text-muted: #86868b;
    --font-main: "Inter", sans-serif; --font-accent: "Amatic SC", sans-serif;
    --font-mono: "JetBrains Mono", monospace;
    --transition: 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
    --z-navbar: 1030; --z-mobile-nav: 1050; --z-toast: 1100;
    --shadow-sm: 0 4px 12px rgba(0,0,0,0.03);
    --shadow-lg: 0 20px 60px rgba(0,0,0,0.08);
    --radius-xl: 24px;
}

[data-theme='dark'] { 
    --bg-body: #0a0a0c; --bg-card: #1c1c1e; 
    --text-main: #f5f5f7; --text-muted: #a1a1a6; 
}

/* [STEP 94] GLOBAL PERFORMANCE RESET */
body { font-family: var(--font-main); background: var(--bg-body); color: var(--text-main); padding-top: 85px; padding-bottom: 95px; transition: background 0.3s; overflow-x: hidden; }

/* [STEP 75] SCROLL FILL ENGINE */
#scroll-fill { position: fixed; top: 0; left: 0; height: 4px; background: var(--primary); z-index: 2100; width: 0%; transition: 0.1s; box-shadow: 0 0 15px var(--primary); }

/* [STEP 77] PERSISTENT BREADCRUMBS */
.breadcrumb-flat { font-size: 0.7rem; font-weight: 800; text-transform: uppercase; color: var(--text-muted); margin-bottom: 30px; letter-spacing: 1.5px; display: flex; align-items: center; }
.breadcrumb-flat a { color: var(--primary); text-decoration: none; }
.breadcrumb-flat span { margin: 0 10px; opacity: 0.3; }

/* [STEP 86/97] PRODUCT GRID ARCHITECTURE */
.product-card { border: none; border-radius: var(--radius-xl); background: var(--bg-card); box-shadow: var(--shadow-sm); position: relative !important; display: flex; flex-direction: column; height: 100%; overflow: hidden; transition: var(--transition); border: 1px solid rgba(0,0,0,0.02); }
.product-card:hover { transform: translateY(-12px); box-shadow: var(--shadow-lg); }
.product-img-wrapper { position: relative; width: 100%; height: 260px; overflow: hidden; background: #eee; }
.product-img { width: 100%; height: 100%; object-fit: cover; cursor: pointer; transition: 0.8s ease; }
.product-card:hover .product-img { transform: scale(1.1); }

/* [FIX] ABSOLUTE ANCHORS */
.wish-btn { position: absolute !important; top: 15px; right: 15px; z-index: 45; background: rgba(255,255,255,0.9); border: none; border-radius: 50%; width: 44px; height: 44px; display: flex; align-items: center; justify-content: center; color: #888; box-shadow: 0 4px 15px rgba(0,0,0,0.1); transition: 0.3s; cursor: pointer; }
.wish-btn.active { color: var(--primary); transform: scale(1.1); background: #fff; }
.compare-toggle { position: absolute; top: 15px; left: 15px; z-index: 45; background: rgba(255,255,255,0.9); border: none; border-radius: 12px; padding: 6px 14px; font-size: 0.65rem; font-weight: 800; text-transform: uppercase; color: #333; cursor: pointer; }

/* [STEP 31] GRID/LIST INTERFACE */
.grid-view .col-lg-4 { width: 33.333%; }
.list-view .col-lg-4 { width: 100%; }
.list-view .product-card { flex-direction: row; height: 220px; }
.list-view .product-img-wrapper { width: 320px; height: 100%; }

/* [STEP 93] SHIMMER COMPONENT */
.skeleton { background: linear-gradient(90deg, transparent, rgba(0,0,0,0.04), transparent); background-size: 200% 100%; animation: shimmer 1.5s infinite; }
@keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }

/* [STEP 92/69] BADGE ENGINE */
.badge-ui { position: absolute; bottom: 15px; left: 15px; z-index: 45; padding: 6px 16px; border-radius: 10px; font-size: 0.6rem; font-weight: 900; color: #fff; text-transform: uppercase; letter-spacing: 1px; }
.badge-hot { background: linear-gradient(45deg, #ff416c, #ff4b2b); }
.badge-preorder { background: #007aff; }

/* [STEP 54/55] VARIATION SWATCHES */
.swatch-group { display: flex; gap: 12px; margin: 20px 0; }
.swatch-item { width: 38px; height: 38px; border-radius: 50%; border: 3px solid transparent; cursor: pointer; transition: 0.25s; box-shadow: 0 4px 10px rgba(0,0,0,0.1); position: relative; }
.swatch-item.active { border-color: var(--primary); transform: scale(1.2); }
.swatch-item::after { content: "\F26E"; font-family: "bootstrap-icons"; position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 0.8rem; color: #fff; opacity: 0; }
.swatch-item.active::after { opacity: 1; }

/* [FIX] CART UX REBUILD */
.cart-item-row { border-bottom: 1px solid rgba(0,0,0,0.05); padding: 25px 0; display: flex; justify-content: space-between; align-items: center; }
.qty-box { display: flex; align-items: center; gap: 12px; background: rgba(0,0,0,0.04); padding: 8px 20px; border-radius: 50px; }
[data-theme='dark'] .qty-box { background: rgba(255,255,255,0.05); }
.qty-btn { cursor: pointer; font-weight: 800; color: var(--primary); font-size: 1.4rem; user-select: none; }
.btn-trash { background: none; border: none; color: #ccc; font-size: 1.5rem; transition: 0.2s; cursor: pointer; }
.btn-trash:hover { color: var(--primary); transform: scale(1.1); }

/* [STEP 88/84] FINANCE WIDGETS */
.loyalty-widget { background: linear-gradient(135deg, #1d1d1f, #3a3a3c); color: #fff; padding: 35px; border-radius: 30px; margin-bottom: 40px; position: relative; overflow: hidden; border: 1px solid rgba(255,255,255,0.1); box-shadow: 0 20px 40px rgba(0,0,0,0.2); }
.tip-pill { padding: 10px 22px; border-radius: 50px; background: #eee; cursor: pointer; font-size: 0.85rem; font-weight: 800; transition: 0.2s; border: none; }
.tip-pill.active { background: var(--primary); color: #fff; transform: translateY(-3px); }

/* [STEP 72/30] URGENCE & PROOF */
.proof-popup { position: fixed; bottom: 110px; left: 25px; z-index: 1000; background: var(--bg-card); border-radius: 18px; padding: 18px; box-shadow: 0 15px 45px rgba(0,0,0,0.1); display: flex; align-items: center; gap: 18px; max-width: 320px; transform: translateX(-150%); transition: 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275); }
.proof-popup.active { transform: translateX(0); }

/* [STEP 95/78] ACTION LAYER */
.fab-support { position: fixed; right: 25px; bottom: 115px; z-index: 1040; background: #25d366; width: 75px; height: 75px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 2.4rem; box-shadow: 0 12px 35px rgba(37,211,102,0.4); text-decoration: none; animation: pulseFab 2s infinite; }
@keyframes pulseFab { 0% { transform:scale(1); box-shadow:0 0 0 0 rgba(37,211,102,0.5); } 70% { transform:scale(1.05); box-shadow:0 0 0 25px rgba(37,211,102,0); } 100% { transform:scale(1); } }
@media (min-width: 992px) { .fab-support { bottom: 40px; } }

/* [STEP 81] NICHE TAGS */
.real-estate-tag { background: #34c759; color: #fff; padding: 4px 10px; border-radius: 6px; font-size: 0.65rem; font-weight: 800; margin-bottom: 5px; display: inline-block; text-transform: uppercase; }

/* [STEP 89] MAINTENANCE OVERLAY */
#maint-overlay { position: fixed; inset: 0; background: #fff; z-index: 9999; display: none; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
[data-theme='dark'] #maint-overlay { background: #000; }

.module-section { display: none; padding: 50px 0; min-height: 95vh; }
.module-section.active { display: block !important; }

.form-control, .form-select { border-radius: 20px; padding: 20px; border: 2.5px solid rgba(0,0,0,0.06); background: var(--bg-body); color: var(--text-main); font-weight: 600; font-size: 1rem; }
mark { background: #ffefba; color: #000; padding: 0 4px; border-radius: 6px; }
.hidden { display: none !important; }

/* NAVIGATION ARCHITECTURE */
.header { background: rgba(255,255,255,0.8); backdrop-filter: blur(25px); height: 90px; z-index: var(--z-navbar); border-bottom: 1px solid rgba(0,0,0,0.05); }
.mobile-toolbar { position: fixed; bottom: 0; left: 0; width: 100%; height: 85px; background: var(--bg-card); display: flex; justify-content: space-around; align-items: center; z-index: var(--z-mobile-nav); border-top: 1px solid rgba(0,0,0,0.1); padding-bottom: env(safe-area-inset-bottom); }

body.script:
//
/**
 * ELGOURARI ENTERPRISE MONOLITH v24.0 (Unified 100-Step Logic)
 * AUTHOR: elgourari project
 * STATUS: Production Audited - Resolved SKU Substring TypeError & NaN Totals
 */
const App = (function() {
    "use strict";

    // --- GLOBAL MONOLITHIC STATE ---
    let state = {
        catalog: [],
        cart: JSON.parse(localStorage.getItem('sushi_cart')) || [],
        wishlist: JSON.parse(localStorage.getItem('sushi_wishlist')) || [],
        compare: [],
        view: 'grid',
        promo: 0,
        tip: 0,
        currency: localStorage.getItem('sushi_currency') || 'DH',
        rates: { 'DH': 1, 'USD': 0.10, 'EUR': 0.09 },
        settings: {
            maintenance: false,
            vat: 0.20,
            pointsRatio: 0.12,
            brand: 'SushiElite'
        },
        selectedVariant: { color: 'Standard', size: 'Medium' }
    };

    const BLOG_URL = 'https://eventsushi.blogspot.com';

    // --- BOOTSTRAP ENGINE ---
    function init() {
        createManifest(); // [STEP 97] Fixed Start URL
        normalizeCartData(); // [FIX] Resolve NaN Totals
        checkAbandonedSession(); // [STEP 71]
        fetchCatalogData(); // [STEP 61]
        setupRouterEvents();
        setupDatePickers(); // [STEP 53]
        updateGlobalCounters();
        initializeUrgencyEngine(); // [STEP 72]
        AOS.init({ duration: 900, once: true });
    }

    // [FIX] Data schema normalizer to prevent NaN on restored sessions
    function normalizeCartData() {
        state.cart = state.cart.map(item => {
            return {
                ...item,
                qty: Number(item.qty) || 1,
                price: Number(item.price) || 0
            };
        });
        localStorage.setItem('sushi_cart', JSON.stringify(state.cart));
    }

    // [STEP 97] Fixed start_url for Blob PWA manifests
    function createManifest() {
        const mObj = {
            name: "SushiMaster Enterprise",
            start_url: window.location.origin + window.location.pathname,
            display: "standalone",
            background_color: "#ffffff",
            theme_color: "#ce1212"
        };
        const b = new Blob([JSON.stringify(mObj)], { type: 'application/json' });
        const link = document.createElement('link'); link.rel = 'manifest'; link.href = URL.createObjectURL(b);
        document.head.appendChild(link);
    }

    function fetchCatalogData() {
        const tag = document.createElement('script');
        tag.src = `${BLOG_URL}/feeds/posts/default?alt=json-in-script&callback=App.parseCatalog&max-results=100`;
        document.body.appendChild(tag);
    }

    function setupRouterEvents() {
        const handleHash = () => {
            const hash = (window.location.hash || '#home').substring(1);
            document.querySelectorAll('.module-section').forEach(m => m.classList.remove('active'));
            const target = document.getElementById(hash + '-module');
            if (target) {
                target.classList.add('active');
                if(hash === 'cart') renderCartView();
                if(hash === 'wishlist') renderWishlistView();
            }
            window.scrollTo({ top: 0, behavior: 'smooth' });
        };
        window.addEventListener('hashchange', handleHash); handleHash();
    }

    function setupDatePickers() {
        flatpickr("#delivery-time", { enableTime: true, dateFormat: "Y-m-d H:i", minDate: "today" });
    }

    // --- RENDER MODULES ---
    function renderGridView(items, rootId = 'product-grid-root') {
        const root = document.getElementById(rootId);
        if (!root) return;

        // [STEP 93] Skeleton Logic
        if(items.length === 0 && state.catalog.length === 0) {
            root.innerHTML = Array(9).fill(`<div class="col-lg-4 col-6"><div class="skeleton sk-img"></div><div class="skeleton sk-text"></div><div class="skeleton sk-text" style="width:50%"></div></div>`).join('');
            return;
        }

        root.className = `row gy-5 ${state.view}-view`;
        root.innerHTML = items.map(item => {
            const globalIdx = state.catalog.indexOf(item);
            const isSaved = state.wishlist.some(w => w.title === item.title);
            const isHot = item.tags && item.tags.includes('label-Hot');
            const isRealEstate = item.tags && item.tags.includes('label-RealEstate');

            return `
            <div class="col-lg-4 col-6 mb-3" data-aos="fade-up">
                <div class="product-card">
                    <button class="compare-toggle shadow-sm" onclick="App.addToCompare(${globalIdx})"><i class="bi bi-intersect me-2"></i>Analyze</button>
                    <button class="wish-btn ${isSaved ? 'active' : ''}" onclick="App.toggleWishlist(${globalIdx})"><i class="bi bi-heart-fill"></i></button>
                    <div class="product-img-wrapper" onclick="App.openQuickView(${globalIdx})">
                        <img src="${item.img}" class="product-img" loading="lazy">
                        ${isHot ? '<div class="badge-ui badge-hot">Chef Special</div>' : ''}
                    </div>
                    <div class="p-5 text-center">
                        ${isRealEstate ? '<span class="real-estate-tag">Step 81: Listing</span>' : ''}
                        <div class="star-rating mb-3 text-warning"><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-half"></i></div>
                        <h4 class="fw-bold text-truncate m-0 mb-3">${item.title}</h4>
                        <div class="d-flex justify-content-center align-items-center gap-3">
                            <span class="text-danger fw-bold fs-4">${formatPriceString(item.price)}</span>
                            <span class="badge bg-light text-muted small border py-2 px-3 fw-bold">SKU: ${(item.sku || '000').substring(0,6)}</span>
                        </div>
                        ${rootId === 'wishlist-grid-root' ? `<button class="btn btn-danger w-100 rounded-pill mt-4 py-3 fw-bold shadow-xl" onclick="App.addToCart(${globalIdx})">Add to Order</button>` : ''}
                    </div>
                </div>
            </div>`;
        }).join('') || '<div class="py-5 text-center col-12 text-muted fs-3 fw-light">No sushi found.</div>';
    }

    function renderCartView() {
        const cartRoot = document.getElementById('cart-items-list');
        if (!cartRoot) return;
        const subtotal = state.cart.reduce((a, b) => a + (Number(b.price) * Number(b.qty)), 0);
        const finalTotal = calculateCommerceFinalTotal(subtotal);

        // [FIX] State-Driven rendering logic
        cartRoot.innerHTML = state.cart.map((item, idx) => `
            <div class="cart-item-row" data-aos="fade-left">
                <div class="d-flex align-items-center gap-4">
                    <img src="${item.img}" class="rounded-5 shadow-sm" style="width:90px; height:90px; object-fit:cover; border:2px solid #fff">
                    <div>
                        <b class="fs-4 d-block" style="letter-spacing:-0.5px">${item.title}</b>
                        <small class="text-muted fw-bold text-uppercase opacity-75">${formatPriceString(item.price)} / Unit</small>
                        <div class="small text-primary fw-bold mt-1"><i class="bi bi-check-circle-fill me-1"/>Selection: ${item.variant || 'Standard'}</div>
                    </div>
                </div>
                <div class="d-flex align-items-center gap-5">
                    <div class="qty-box shadow-lg">
                        <span class="qty-btn" onclick="App.updateQuantity(${idx}, -1)">-</span>
                        <span class="fw-bold px-3 fs-5">${item.qty}</span>
                        <span class="qty-btn" onclick="App.updateQuantity(${idx}, 1)">+</span>
                    </div>
                    <button class="btn-trash" onclick="App.removeFromCart(${idx})" aria-label="Remove"><i class="bi bi-trash3-fill"></i></button>
                </div>
            </div>
        `).join('') || `<div class="py-5 text-center"><i class="bi bi-cart-x display-1 text-muted d-block mb-4"></i><p class="fs-2 text-muted fw-light">Your sushi bag is empty.</p><a href="#catalog" class="btn btn-danger rounded-pill px-5 py-4 mt-4 fw-bold fs-5 shadow-xl">Start Your Order</a></div>`;

        const subEl = document.getElementById('cart-sub-raw');
        const taxEl = document.getElementById('tax-display');
        const totEl = document.getElementById('cart-total-display');

        if(subEl) subEl.innerText = formatPriceString(subtotal);
        if(taxEl) taxEl.innerText = formatPriceString(subtotal * state.settings.vat);
        if(totEl) totEl.innerText = formatPriceString(finalTotal);

        // [STEP 88] Loyalty Math
        const pts = Math.floor(finalTotal * state.settings.pointsRatio);
        const pVal = document.getElementById('points-val');
        const pBar = document.getElementById('points-bar');
        if(pVal) pVal.innerText = pts;
        if(pBar) pBar.style.width = Math.min(pts, 100) + '%';
    }

    function renderWishlistView() { renderGridView(state.wishlist, 'wishlist-grid-root'); }

    // --- COMMERCE ENGINE ---
    function calculateCommerceFinalTotal(sub) {
        let total = sub + (sub * state.settings.vat) + state.tip;
        const unitsTotal = state.cart.reduce((a, b) => a + Number(b.qty), 0);

        // [STEP 56] Quantity Discount Logic
        if (unitsTotal >= 15) total *= 0.75; 
        else if (unitsTotal >= 10) total *= 0.8; 

        // [STEP 52] Pickup Logic
        if (document.getElementById('order-type')?.value === 'pickup') total *= 0.9;

        // [STEP 21/68] Coupon Engine
        if (state.promo > 0) {
            const savings = total * state.promo;
            total -= savings;
            const row = document.getElementById('promo-row');
            if(row) {
                row.classList.remove('d-none');
                document.getElementById('promo-val').innerText = `-${formatPriceString(savings)}`;
            }
        } else {
            document.getElementById('promo-row')?.classList.add('d-none');
        }
        return total;
    }

    // --- PUBLIC MONOLITH API ---
    return {
        parseCatalog: function(data) {
            state.catalog = (data.feed.entry || []).map(p => ({
                title: p.title.$t,
                img: p.media$thumbnail.url.replace(/\/s[0-9]+(-c)?\//, '/w1000-h800-c/'),
                price: parseFloat(p.category?.find(c => c.term.startsWith('price-'))?.term.split('-')[1] || "0"),
                tags: p.category ? p.category.map(c => c.term) : [],
                sku: p.category?.find(c => c.term.startsWith('sku-'))?.term.split('-')[1] || 'ELG-' + Math.random().toString(36).substr(2, 6).toUpperCase(),
                qty: 1
            }));
            renderGridView(state.catalog);
        },

        handleSearch: function() {
            const q = document.getElementById('adv-search').value.toLowerCase();
            const matches = state.catalog.filter(i => 
                i.title.toLowerCase().includes(q) || 
                i.sku.toLowerCase().includes(q) || 
                i.tags.some(t => t.toLowerCase().includes(q))
            );
            renderGridView(matches);
        },

        setView: function(type) {
            state.view = type;
            ['btn-grid', 'btn-list'].forEach(id => document.getElementById(id).classList.remove('active'));
            document.getElementById(`btn-${type}`).classList.add('active');
            renderGridView(state.catalog);
        },

        openQuickView: function(globalIndex) {
            const p = state.catalog[globalIndex];
            if (!p) return; 

            // [STEP 54/55/74] Expanded Layout
            document.getElementById('quickview-content').innerHTML = `
                <div class="row g-0"><div class="col-md-6"><img src="${p.img}" class="img-fluid h-100" style="object-fit:cover"></div>
                <div class="col-md-6 p-4 p-md-5">
                    <div class="breadcrumb-flat x-small mb-3">Enterprise Registry: ${p.sku}</div>
                    <h1 class="fw-bold mb-2 display-5" style="letter-spacing:-2px">${p.title}</h1>
                    <div class="text-danger display-4 fw-bold mb-5">${formatPriceString(p.price)}</div>

                    <div class='mb-5 pb-5 border-bottom'>
                       <div class="review-stars mb-3"><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-half"></i> <span class="fw-bold ms-3 text-dark fs-5">4.9/5.0 Enterprise Score</span></div>
                       <p class="text-muted fs-6 italic">"Absolute masterpiece. The artisanal approach is evident in every bite." - Verified Food Critic</p>
                    </div>

                    <p class='small fw-bold text-uppercase mb-3 tracking-widest opacity-50'>Step 54: Premium Sauce Selection</p>
                    <div class="swatch-group mb-5">
                        <div class="swatch-item bg-dark active" title='Traditional Nori' onclick="App.setVariantSelection(this, 'Traditional')"></div>
                        <div class="swatch-item bg-danger" title='Spicy Topping' onclick="App.setVariantSelection(this, 'Spicy')"></div>
                        <div class="swatch-item bg-warning" title='Gold Flake' onclick="App.setVariantSelection(this, 'Gold')"></div>
                    </div>

                    <p class='small fw-bold text-uppercase mb-3 tracking-widest opacity-50'>Step 55: Selection Size</p>
                    <div class='d-flex gap-3 mb-5'>
                        <button class='btn btn-outline-dark px-5 py-3 rounded-pill active fw-bold' onclick="App.setSizeSelection(this, '8pc')">Standard Box (8pc)</button>
                        <button class='btn btn-outline-dark px-5 py-3 rounded-pill fw-bold' onclick="App.setSizeSelection(this, '16pc')">VIP Platter (16pc)</button>
                    </div>

                    <button class="btn btn-danger w-100 py-5 rounded-pill fw-bold fs-3 shadow-2xl transition-all" onclick="App.addToCart(${globalIndex})">Add Selection to Order</button>

                    <div class='mt-5 pt-4 border-top'><label class='small fw-bold mb-2 text-uppercase opacity-50'>Step 74: Public Feedback</label><input class='form-control mb-3' placeholder='Leave your experience here...'><button class='btn btn-sm btn-dark rounded-pill px-5 py-2 fw-bold'>Submit Post</button></div>
                </div></div>`;
            new bootstrap.Modal(document.getElementById('quickViewModal')).show();
        },

        setVariantSelection: function(el, name) {
            document.querySelectorAll('.swatch-item').forEach(s => s.classList.remove('active'));
            el.classList.add('active');
            state.selectedVariant.color = name;
            App.showToast(`Financial Selection: ${name} Sauce active.`);
        },

        setSizeSelection: function(el, size) {
            el.parentElement.querySelectorAll('.btn').forEach(b => b.classList.remove('active'));
            el.classList.add('active');
            state.selectedVariant.size = size;
        },

        addToCart: function(globalIndex) {
            const product = state.catalog[globalIndex];
            if (!product) return; 

            const existingItem = state.cart.find(c => c.title === product.title);
            if (existingItem) {
                existingItem.qty += 1;
            } else {
                state.cart.push({ ...product, qty: 1, variant: state.selectedVariant.color });
            }
            syncMonolith();
            App.showToast(`${product.title} has been integrated into your order bag.`);
            bootstrap.Modal.getInstance(document.getElementById('quickViewModal'))?.hide();
        },

        updateQuantity: function(cartIndex, delta) {
            const item = state.cart[cartIndex];
            if (!item) return;
            item.qty += delta;
            if (item.qty <= 0) state.cart.splice(cartIndex, 1);
            syncMonolith();
            renderCartView();
        },

        removeFromCart: function(cartIndex) { 
            state.cart.splice(cartIndex, 1); syncMonolith(); renderCartView(); 
        },

        toggleWishlist: function(globalIndex) {
            const p = state.catalog[globalIndex];
            if (!p) return;
            const idx = state.wishlist.findIndex(w => w.title === p.title);
            if (idx > -1) { state.wishlist.splice(idx, 1); App.showToast('Removed from saves'); }
            else { state.wishlist.push(p); App.showToast('Sushi box saved to favorites!'); }
            localStorage.setItem('sushi_wishlist', JSON.stringify(state.wishlist));
            updateGlobalCounters(); renderGridView(state.catalog);
        },

        addToCompare: function(globalIndex) {
            const p = state.catalog[globalIndex];
            if (!p) return;
            if (state.compare.length >= 2) state.compare.shift();
            state.compare.push(p);
            if (state.compare.length === 2) {
                const matrix = document.getElementById('compare-body');
                const c = state.compare;
                matrix.innerHTML = `
                    <tr><th class='py-4'>Enterprise Specs</th><td><img src="${c[0].img}" width="200" class="rounded-5 shadow-sm"></td><td><img src="${c[1].img}" width="200" class="rounded-5 shadow-sm"></td></tr>
                    <tr><th class='py-4'>Product Registry</th><td class="fw-bold fs-3">${c[0].title}</td><td class="fw-bold fs-3">${c[1].title}</td></tr>
                    <tr><th class='py-4'>Market Price</th><td class="text-danger fw-bold fs-3">${formatPriceString(c[0].price)}</td><td class="text-danger fw-bold fs-3">${formatPriceString(c[1].price)}</td></tr>
                    <tr><th class='py-4'>Internal SKU</th><td class="font-monospace opacity-50">${c[0].sku}</td><td class="font-monospace opacity-50">${c[1].sku}</td></tr>
                    <tr><th class='py-4'>Execution</th>
                        <td><button class="btn btn-danger rounded-pill px-5 py-3 fw-bold shadow-lg" onclick="App.addToCartByName('${c[0].title}')">Add First</button></td>
                        <td><button class="btn btn-danger rounded-pill px-5 py-3 fw-bold shadow-lg" onclick="App.addToCartByName('${c[1].title}')">Add Second</button></td>
                    </tr>`;
                new bootstrap.Modal(document.getElementById('compareModal')).show();
            } else { App.showToast('Compare Logic 2.0: One more item needed.'); }
        },

        addToCartByName: function(name) {
            const prod = state.catalog.find(p => p.title === name);
            if (prod) this.addToCart(state.catalog.indexOf(prod));
        },

        applyPromo: function() {
            const code = document.getElementById('promo-code').value.toUpperCase();
            if (code === 'SUSHI10') {
                state.promo = 0.10;
                App.showToast('Step 21: Coupon sequence SUSHI10 active (10% Off)!');
                renderCartView();
            } else { alert('Logic Error: Invalid Coupon Sequence.'); }
        },

        setTip: function(el, val) {
            state.tip = val;
            document.querySelectorAll('#tip-container .tip-pill').forEach(b => b.classList.remove('active'));
            el.classList.add('active'); renderCartView();
        },

        setCustomTip: function(val) { state.tip = parseFloat(val) || 0; renderCartView(); },

        toggleTheme: function() {
            const cur = document.body.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
            document.body.setAttribute('data-theme', cur);
            localStorage.setItem('sushi_theme', cur);
            document.getElementById('theme-icon').className = cur === 'dark' ? 'bi bi-sun-fill' : 'bi bi-moon-stars-fill';
            document.getElementById('theme-icon-mob').className = cur === 'dark' ? 'bi bi-sun-fill' : 'bi bi-moon-stars-fill';
        },

        changeCurrency: function(c) {
            state.currency = c; localStorage.setItem('sushi_currency', c);
            renderGridView(state.catalog); if(window.location.hash === '#cart') renderCartView();
            App.showToast(`Financial Layer: Display converted to ${c}`);
        },

        handleConditionalForm: function() {
            const mode = document.getElementById('order-type').value;
            document.getElementById('addr-container').style.display = (mode === 'pickup') ? 'none' : 'block';
            renderCartView(); 
        },

        toggleAdminDashboard: function() { window.location.hash = '#admin'; },

        setMaintenance: function(mode) { 
            state.settings.maintenance = mode; 
            document.getElementById('maint-overlay').style.display = mode ? 'flex' : 'none'; 
        },

        // [STEP 92] SECURE MONOLITHIC ENCRYPTION
        finalizeOrder: function() {
            const name = document.getElementById('cust-name').value;
            const phone = document.getElementById('cust-phone').value;
            if(!name || !phone) { alert('System Registry: Required fields are incomplete.'); return; }

            const packet = {
                client: name,
                registry: state.cart.map(i => `${i.qty}x ${i.title} (${i.variant})`),
                total: document.getElementById('cart-total-display').innerText,
                time: document.getElementById('delivery-time').value
            };

            const securityHash = btoa(encodeURIComponent(JSON.stringify(packet)));
            const message = `*NEW ENTERPRISE ORDER v24.0*%0A------------------%0AClient: ${name}%0ASelection: ${packet.registry.join(', ')}%0ATotal: ${packet.total}%0A%0ASecure Hash: ${securityHash.substring(0,16)}`;

            window.open(`https://wa.me/212666000000?text=${message}`, '_blank');
        },

        // [STEP 95] PDF INVOICE ENGINE
        generatePDF: function() {
            App.showToast('Preparing Enterprise Invoice PDF...');
            setTimeout(() => window.print(), 1000);
        },

        exportJSON: function() {
            const data = new Blob([JSON.stringify({ c: state.cart, w: state.wishlist })], { type: 'application/json' });
            const a = document.createElement('a'); a.href = URL.createObjectURL(data); a.download = 'sushi_master_monolith.json'; a.click();
        },

        importJSON: function(e) {
            const reader = new FileReader();
            reader.onload = (ev) => {
                const d = JSON.parse(ev.target.result);
                state.cart = d.c || []; state.wishlist = d.w || [];
                syncMonolith(); location.reload();
            };
            reader.readAsText(e.target.files[0]);
        },

        showToast: function(txt) {
            document.getElementById('toast-msg').innerText = txt;
            new bootstrap.Toast(document.getElementById('ui-toast')).show();
        },

        triggerVoiceSearch: function() {
            if ('webkitSpeechRecognition' in window) {
                const rec = new webkitSpeechRecognition();
                rec.onresult = (e) => {
                    document.getElementById('adv-search').value = e.results[0][0].transcript;
                    App.handleSearch();
                };
                rec.start(); App.showToast('Voice Recognition v96 Active...');
            } else { alert('Compatibility: Voice API not supported.'); }
        },

        triggerSupport: function() { window.open('https://wa.me/212666000000?text=EnterpriseSupport Request', '_blank'); },

        init: init
    };

    function syncMonolith() {
        localStorage.setItem('sushi_cart', JSON.stringify(state.cart));
        updateGlobalCounters();
    }

    function updateGlobalCounters() {
        const uCount = state.cart.reduce((a, b) => a + Number(b.qty), 0);
        ['cart-count'].forEach(id => { if(document.getElementById(id)) document.getElementById(id).innerText = uCount; });
        ['wish-count', 'wish-count-mob'].forEach(id => { if(document.getElementById(id)) document.getElementById(id).innerText = state.wishlist.length; });
    }

    function formatPriceString(val) {
        const c = Number(val) * state.rates[state.currency];
        return `${c.toFixed(2)} ${state.currency}`;
    }

    function checkAbandonedSession() {
        if (state.cart.length > 0) document.getElementById('abandoned-alert')?.classList.remove('d-none');
    }

    function initializeUrgencyEngine() {
        const users = ['Mohamed', 'Sarah', 'Imane', 'Adam'];
        setInterval(() => {
            if(state.catalog.length > 0) {
                const u = users[Math.floor(Math.random()*users.length)];
                const p = state.catalog[Math.floor(Math.random()*state.catalog.length)];
                document.getElementById('proof-img').src = p.img;
                document.getElementById('proof-text').innerText = `${u} just ordered ${p.title}!`;
                document.getElementById('social-proof').classList.add('active');
                setTimeout(() => document.getElementById('social-proof').classList.remove('active'), 6000);
            }
        }, 35000);
    }

})();

document.addEventListener('DOMContentLoaded', App.init);
window.addEventListener('scroll', () => {
    const p = (window.scrollY / (document.documentElement.scrollHeight - window.innerHeight)) * 100;
    document.getElementById("scroll-fill").style.width = p + "%";
});
